import{_ as i,l,o as e,c as n,v as t,p as s,x as r,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"ROP","description":"","frontmatter":{"title":"ROP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rop.md","filePath":"cs/rop.md","lastUpdated":1789023840000}'),p={name:"cs/rop.md"};function E(_,a,A,m,C,P){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="rop" tabindex="-1">ROP <a class="header-anchor" href="#rop" aria-label="Permalink to &quot;ROP&quot;">​</a></h1><div class="epigraph"><p>栈不可执行之后，控制流仍可被改成「已有代码的短片段」再串起来。返回导向等于把程序里的 ret 当成指令集。防御是控制流完整性与减少可用碎片，不是再加长 canary。</p><footer>—— Shacham, The Geometry of Innocent Flesh on the Bone, CCS 2007；对照 Abadi 等 CFI</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/stack-canary">canary</a>挡连续踏帧。缺口是<strong>返回地址仍可被改向已映射可执行页</strong>。ROP 是这种能力的名字。本课说明为何 NX 不够，以及 ASLR/CFI/影子栈要对付什么——不提供 gadget 收集或利用链。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>NX 禁止数据上取指。若攻击者能写返回地址（或等价控制数据），可跳到已有指令序列的末尾 <code>ret</code>，再弹下一个。缺口是：可执行镜像成了指令仓库。课程只承认这一事实。</p><h3 id="禁止利用链" tabindex="-1">禁止利用链 <a class="header-anchor" href="#禁止利用链" aria-label="Permalink to &quot;禁止利用链&quot;">​</a></h3><p>不列出 gadget、不写链、不给工具命令。工程课要的是：开 CFI、影子栈、减少 RWX、及时打补丁。</p><p><span class="marginnote">Shacham 2007。ASLR 提高定位代价，不是证明。本课与<a href="/cs/side-channel">侧信道</a>的信息泄漏正交：泄漏会削弱 ASLR。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用「控制数据 → 已有代码」一句话收机制。列出缓解：ASLR、CFI、影子栈（后课）、指针认证（再后）。强调内存安全语言从根上缩小该类。</p>',12)),(e(),s(c,null,{default:r(()=>[h(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20NX%5B%22%E6%A0%88%E4%B8%8D%E5%8F%AF%E6%89%A7%E8%A1%8C%22%5D%20--%3E%20STILL%5B%22%E4%BB%8D%E5%8F%AF%E6%94%B9%E8%BF%94%E5%9B%9E%E5%9C%B0%E5%9D%80%22%5D%0A%20%20STILL%20--%3E%20FRAG%5B%22%E5%B7%B2%E6%9C%89%E5%8F%AF%E6%89%A7%E8%A1%8C%E7%A2%8E%E7%89%87%22%5D%0A%20%20FRAG%20--%3E%20CFI%5B%22CFI%20%2F%20%E5%BD%B1%E5%AD%90%E6%A0%88%E7%BC%A9%E5%B0%8F%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>完整性要从「页不可执行」升级到「跳转目标合法」。下一课 JOP/COP：不以 <code>ret</code> 为唯一缝合，同一防御族。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课无 PoC。JOP/COP 下一课只对照缝合原语。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>canary/NX 不够：返回地址仍能指向已有代码。</li><li>ROP 是控制流劫持的一种缝合方式。</li><li>CFI、ASLR、影子栈是防御方向。</li><li>下一课 JOP/COP。</li><li>出处：Shacham, CCS 2007；Abadi et al., CFI。</li></ul>',8))])}const S=i(p,[["render",E]]);export{f as __pageData,S as default};
